);

SELECT
  100.0 * COUNT(*) FILTER (
    WHERE "c"."language" = 'French'
  ) / NULLIF(COUNT(*), 0) AS "percentage"
FROM "cards" AS "c"
WHERE ("c"."power" IS NULL OR "c"."power" = '*');

SELECT
    100.0 * COUNT(*) FILTER (
        WHERE LOWER(TRIM("language")) = 'french'
    ) / NULLIF(COUNT(*), 0) AS "percentage"
FROM "cards" AS c
WHERE c."isstoryspotlight" = 1;

SELECT COUNT(*) AS "total_comments"
FROM "comments" AS "c"
WHERE "c"."userid" = 13;

SELECT COUNT(*) AS "count"
FROM "member" AS m
WHERE LOWER(TRIM(m."position")) = 'president';
